package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Puts the person on hold, or takes them off it when they are held. Read afresh and locked, so
 *  two toggles at once happen one after the other. Not an edit: the person's version is untouched,
 *  so an editor open on them can still save. Publishes the person as they are now. */
public class HoldPerson {
    public void hold(@Val Person loaded, People people, Out<Person> person) throws PersonNotFoundException {
        Person current = people.lock(loaded.getSheetId(), loaded.getId());
        if (current == null) throw new PersonNotFoundException(loaded.getId());
        current.setHeld(!current.isHeld());
        people.saveHold(current);
        person.set(current);
    }
}
